/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void eips_alert_timeout_stop(void)
{
  if(!timeout_test(eips_vars.timeout_alert))
    {
      timeout_stop(eips_vars.timeout_alert) ;
     
      #if DBG_EIPS == 1
        dbg_tx_text("\nEIPS Alert Timeout Stop")  ;
      #endif
    }              
}
